import type { MedusaContainer, RemoteQueryInput } from "@medusajs/framework/types"
import { ContainerRegistrationKeys } from "@medusajs/framework/utils"

/**
 * `query.graph` returns untyped rows until `.medusa/types` is generated by a running server, which
 * CI never does. This wrapper gives each call site an explicit row type for the fields it asks for.
 */
export async function queryList<T>(
  container: MedusaContainer,
  input: RemoteQueryInput<string>,
): Promise<T[]> {
  const query = container.resolve(ContainerRegistrationKeys.QUERY)
  const { data } = await query.graph(input)
  return data as T[]
}

/** Rows that carry the ids of their linked sales channels (`sales_channels.id`). */
export type WithSalesChannels = { sales_channels?: ({ id: string } | null)[] | null }
